// Genuary #12: Subdivision
// Based on 0b5vr shader https://www.shadertoy.com/view/NsKGDy


#define fs(u) textureLod(iChannel0, u, 0.).x
#define AAstep(thre, val) smoothstep(-.7,.7,(val-thre)/min(0.02,fwidth(val-thre)))

struct octree{
    vec2 center;
    vec2 size;
    float id;
};

// iq's article https://iquilezles.org/articles/distfunctions2d/ 
float sdSegment( in vec2 p, in vec2 a, in vec2 b )
{
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h );
}

octree frame (vec2 p, vec2 scale)
{
    float MIN_SIZE = .25,
    seed = floor( iTime / 3.0 )+.1,
    id;

    vec2 domainMin = vec2(-.5) * scale,
    domainMax = vec2(.5) * scale,
    dim = domainMax - domainMin;

    for (float i = 0.; i<8.; i++)
    {
        vec2 divCenter = vec2( fs( vec2(i + id, seed*0.3) ), 
                                fs( vec2(i + id + 4.3, seed*0.1) )
        );

        divCenter = divCenter * dim + domainMin;
        divCenter = clamp( divCenter, domainMin + MIN_SIZE, domainMax - MIN_SIZE);

        vec2 minSizeOfAxis = min( abs( domainMin - divCenter ), abs( domainMax - divCenter ) );
        float minSize = min( minSizeOfAxis.x,minSizeOfAxis.y);
        if (minSize < MIN_SIZE) break;

        domainMax = mix( domainMax, divCenter, step( p, divCenter ) ),
        domainMin = mix( divCenter, domainMin, step( p, divCenter ) );
        dim = domainMax - domainMin;

        vec2 diff = mix( -divCenter, divCenter, step( p, divCenter ) );
        id = length( diff);
    }

    vec2 center = (domainMax + domainMin)/2.;

    return octree(center, (domainMax - domainMin)/2., id) ;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.*fragCoord-iResolution.xy)/iResolution.y;
    uv *= 2.;

    octree O = frame(uv, vec2(7.1, 4)); 
    float off = .65;

    vec2 a = vec2(O.center-O.size*off), 
    b = vec2(O.center+O.size*off),
    c = vec2(O.center-vec2(O.size.x*off, -O.size.y*off)), 
    d = vec2(O.center+vec2(O.size.x*off, -O.size.y*off));

    float f = AAstep(0.01, abs(sdSegment(uv, a, b)-.03));
    f *= AAstep(0.01,abs(sdSegment(uv, c, d)-.03));
    vec3 col = 1.-vec3(f);
    col *= vec3(fs(vec2(O.id*.27, 0.)), O.id*.2, 1.);

    fragColor = vec4(sqrt(clamp(col, 0., 1.)),1.0);
}
